    aspekt: SemanticExplanationMatch['dopasowanyAspekt'];
  }

  stała punktacja: ScoredItem[] = [];

  for (stałe filtrowanej) {
    niech wynik = 0;
    niech matchedAspect: SemanticExplanationMatch['matchedAspect'] = 'angielski';

    const normEn = normalizeText(s.english);
